#pragma once

#include "AlgorithmTypes.cuh"
#include "States.cuh"
#include "VeloConsolidated.cuh"

namespace PVFinder {

constexpr float OVERLAP_WIDTH = 2.5f;
constexpr unsigned MAX_LAYERS = 6;
constexpr unsigned MAX_LAYER_SIZE = 100;
constexpr unsigned WARP_SIZE = 32;
constexpr unsigned HISTOGRAM_SIZE = 100;
constexpr unsigned NUM_INTERVALS = 40;

// Compile-time model constants (to be generated by script)
#include "ModelConstants.cuh"

// Define constant arrays for input mean and std
__constant__ float d_input_mean[9];
__constant__ float d_input_std[9];

struct BeamLine {
    __host__ __device__ float x() const { return 0.f; }
    __host__ __device__ float y() const { return 0.f; }
    __host__ __device__ float z() const { return 0.f; }
    __host__ __device__ float tx() const { return 0.f; }
    __host__ __device__ float ty() const { return 0.f; }
};

struct Parameters {
    HOST_INPUT(host_number_of_events_t, unsigned) host_number_of_events;
    DEVICE_INPUT(dev_number_of_events_t, unsigned) dev_number_of_events;
    DEVICE_INPUT(dev_velo_tracks_view_t, Allen::Views::Velo::Consolidated::Tracks) dev_velo_tracks_view;
    DEVICE_INPUT(dev_velo_states_view_t, Allen::Views::Physics::KalmanStates) dev_velo_states_view;
    DEVICE_OUTPUT(dev_output_histogram_t, float) dev_output_histogram;
};

// Main kernel function
__global__ void pv_finder_kernel(Parameters parameters);

struct PVFinder_t : public DeviceAlgorithm, Parameters {
    void set_arguments_size(ArgumentReferences<Parameters> arguments, const RuntimeOptions&, const Constants&) const;
    void operator()(
        const ArgumentReferences<Parameters>& arguments,
        const RuntimeOptions&,
        const Constants&,
        const Allen::Context& context) const;

private:
    Allen::Property<dim3> m_block_dim {this, "block_dim", {256, 1, 1}, "block dimensions"};
    Allen::Property<unsigned> m_max_tracks_per_event {this, "max_tracks_per_event", 1000, "Maximum tracks to process per event"};
    Allen::Property<bool> m_enable_fast_math {this, "enable_fast_math", true, "Enable fast math approximations"};
    std::vector<unsigned> layer_sizes = {9, 20, 20, 20, 20, 20, 100};
};

// device functions
__device__ __forceinline__ void assign_intervals(float z_poca, int& interval1, int& interval2, bool& has_second);
__device__ __forceinline__ bool state_poca(
    const Allen::Views::Physics::KalmanState& state,
    const BeamLine& beam_line,
    float& poca_x, float& poca_y, float& poca_z);
__device__ __forceinline__ void calculate_ellipsoid_params(
    const Allen::Views::Physics::KalmanState& state,
    float* ellipsoid_params,
    float& poca_x, float& poca_y, float& poca_z);
__device__ __forceinline__ void neural_network_forward(
    const float* input, float* output);
__device__ __forceinline__ void normalize_for_interval(
    const float* input, float* output, int interval);

// math functions
__device__ __forceinline__ float softplus(float x);
__device__ __forceinline__ float3 normalize(float3 v);
__device__ __forceinline__ float3 cross(float3 a, float3 b);
__device__ __forceinline__ float dot(float3 a, float3 b);

} // namespace PVFinder